import json

lat = json.loads(LATTICE_JSON)

# draw radii per sphere type.  Blue spheres are sized just below touching
# distance (nearest-neighbor spacing: banner 26.12, icon 22.80) so the lattice
# stays separated; yellow spheres overlap their diagonal neighbors by ~2px
# (scaled) so the letters stand out with a slight relief.  The yellow/blue
# ratio is kept the same for all images.
RAD = {'banner_blue': 13.0, 'banner_yellow': 14.2,
       'icon_blue': 11.2, 'icon_yellow': 12.4}

# unified idealized sphere shading: slightly matte body, small glossy
# highlight offset up-left, strong falloff to a dark rim for the 3d effect
BLUE_STOPS = [
    (0.00, (150, 178, 255)),
    (0.08, (120, 152, 255)),
    (0.20, (85, 120, 250)),
    (0.35, (58, 95, 235)),
    (0.50, (44, 78, 215)),
    (0.65, (36, 62, 185)),
    (0.78, (28, 45, 140)),
    (0.88, (14, 22, 80)),
    (0.96, (3, 6, 30)),
    (1.00, (0, 0, 12)),
]
YELLOW_STOPS = [
    (0.00, (255, 253, 90)),
    (0.10, (253, 248, 30)),
    (0.30, (248, 242, 10)),
    (0.50, (232, 225, 6)),
    (0.65, (210, 203, 5)),
    (0.78, (178, 172, 5)),
    (0.88, (135, 130, 5)),
    (0.96, (80, 76, 3)),
    (1.00, (40, 37, 0)),
]
FX, FY = 0.45, 0.325  # gradient focus (fraction of bounding box)

def gradient_def(gid, stops):
    out = [f'  <radialGradient id="{gid}" cx="0.5" cy="0.5" r="0.5" '
           f'fx="{FX}" fy="{FY}">']
    for off, (r, g, b) in stops:
        out.append(f'    <stop offset="{off:g}" stop-color="#{r:02x}{g:02x}{b:02x}"/>')
    out.append('  </radialGradient>')
    return '\n'.join(out)

def lattice_circles(latt, mrange, rb, ry, prec=2):
    """Emit sphere circles; mrange: k -> (mlo, mhi) valid site range per row."""
    x0, dx, y0, dy = latt['x0'], latt['dx'], latt['y0'], latt['dy']
    blues, yellows = [], []
    for k, row in enumerate(latt['grid']):
        m0 = row['m0']
        mlo, mhi = mrange(k)
        y = y0 + k * dy
        for m in range(mlo, mhi + 1):
            i = m - m0
            if i < 0 or i >= len(row['sites']):
                continue
            c = row['sites'][i]
            if c == '.':
                continue
            x = x0 + (k % 2) * dx / 2 + m * dx
            (blues if c == 'B' else yellows).append((x, y))
    lines = []
    for x, y in blues:
        lines.append(f'  <circle cx="{x:.{prec}f}" cy="{y:.{prec}f}" r="{rb}" fill="url(#sb)"/>')
    for x, y in yellows:
        lines.append(f'  <circle cx="{x:.{prec}f}" cy="{y:.{prec}f}" r="{ry}" fill="url(#sy)"/>')
    return lines

MBANNER = lambda k: (0, 30) if k % 2 == 0 else (-1, 29)
MICON = lambda k: (0, 6) if k % 2 == 0 else (-1, 5)

# ---------------------------------------------------------------- large logo
W, H = 1204, 598
parts = []
parts.append(f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" '
             f'viewBox="0 0 {W} {H}">')
parts.append('<!-- SVG re-creation of lammps-logo-large.png: sphere lattice and text')
parts.append('     geometry extracted from the original raytraced bitmap; the text')
parts.append('     outlines are traced from the original lettering; sphere shading is')
parts.append('     an idealized gradient shared by all three LAMMPS logo SVGs. -->')
parts.append(' <title>LAMMPS Molecular Dynamics Simulator</title>')
parts.append(' <defs>')
parts.append(gradient_def('sb', BLUE_STOPS))
parts.append(gradient_def('sy', YELLOW_STOPS))
parts.append('''  <filter id="ds" x="-5%" y="-5%" width="112%" height="112%">
    <feGaussianBlur in="SourceAlpha" stdDeviation="5"/>
    <feOffset dx="8.5" dy="8.5" result="off"/>
    <feFlood flood-color="#000000" flood-opacity="0.475"/>
    <feComposite in2="off" operator="in"/>
    <feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>''')
parts.append(' </defs>')
parts.append(f' <rect width="{W}" height="{H}" fill="#ffffff"/>')
parts.append(' <rect x="7" y="7" width="1174" height="568" rx="15" '
             'fill="#000000" filter="url(#ds)"/>')
parts.append(' <g>')
parts.extend(lattice_circles(lat['banner'], MBANNER,
                             RAD['banner_blue'], RAD['banner_yellow']))
parts.append(' </g>')
# text: outlines traced from the original bitmap (Helvetica-Rounded-style)
trace = json.loads(TEXT_TRACE_JSON)
parts.append(' <g transform="translate(60,565) scale(0.025,-0.025)" fill="#ffffff">')
for d in trace:
    parts.append(f'  <path d="{d}"/>')
parts.append(' </g>')
parts.append('</svg>')
open('lammps-logo-large.svg', 'w').write('\n'.join(parts) + '\n')

# ---------------------------------------------------------------- small logo
W2, H2 = 398, 100
parts = []
parts.append(f'<svg xmlns="http://www.w3.org/2000/svg" width="{W2}" height="{H2}" '
             f'viewBox="0 0 {W2} {H2}">')
parts.append('<!-- SVG re-creation of lammps-logo.png (the small banner logo): the')
parts.append('     sphere lattice of the large logo at 1/3 scale. -->')
parts.append(' <title>LAMMPS</title>')
parts.append(' <defs>')
parts.append(gradient_def('sb', BLUE_STOPS))
parts.append(gradient_def('sy', YELLOW_STOPS))
parts.append(' </defs>')
parts.append(f' <rect width="{W2}" height="{H2}" fill="#000000"/>')
parts.append(' <g transform="translate(1.506,-4.067) scale(0.333333)">')
parts.extend(lattice_circles(lat['banner'], MBANNER,
                             RAD['banner_blue'], RAD['banner_yellow']))
parts.append(' </g>')
parts.append('</svg>')
open('lammps-logo.svg', 'w').write('\n'.join(parts) + '\n')

# ---------------------------------------------------------------- icon
parts = []
parts.append('<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" '
             'viewBox="0 0 256 256">')
parts.append('<!-- SVG re-creation of the LAMMPS icon (lammps.ico): sphere lattice')
parts.append('     geometry extracted from the 256x256 original. -->')
parts.append(' <title>LAMMPS icon</title>')
parts.append(' <defs>')
parts.append(gradient_def('sb', BLUE_STOPS))
parts.append(gradient_def('sy', YELLOW_STOPS))
parts.append(' </defs>')
parts.append(' <rect width="256" height="256" fill="#000000"/>')
parts.extend(lattice_circles(lat['icon'], MICON,
                             RAD['icon_blue'], RAD['icon_yellow']))
parts.append('</svg>')
open('lammps.svg', 'w').write('\n'.join(parts) + '\n')

print('wrote lammps-logo-large.svg lammps-logo.svg lammps.svg')
